    wg_carbon: { name: '存根', desc: '凭旧退件存根说明自己经手的范围。', tier: 'rare', group: '翼与巢', hidden: true, hint: '有些旧纸值得保存。' },
    wg_pension_paid: { name: '确实到账', desc: '活到退休后，收到首笔养老金。', tier: 'epic', group: '翼与巢', hidden: false, hint: '留下工资存根，等到审核结束。' },
    wg_clean: { name: '照片裁掉的部分', desc: '多年后重看W公司第一次独立清扫的记录。', tier: 'rare', group: '翼与巢', hidden: true, hint: '培训资料不一定保留整张照片。' },
    wg_rollcall: { name: '仍然应到', desc: '从重发的装备内衬里认出昔日队友的编号。', tier: 'rare', group: '翼与巢', hidden: true, hint: '领取装备时看一眼内衬。' },
    wg_interest: { name: '到期时间', desc: '旧征收对象的时间贷款转到了下一代人身上。', tier: 'rare', group: '翼与巢', hidden: true, hint: '旧账簿可能再次发回。' },
    wg_seal: { name: '只核封条', desc: '重见K公司多年前封存的货箱。', tier: 'rare', group: '翼与巢', hidden: true, hint: '留意清点表上的旧日期。' },
    wg_bed: { name: '下一位住户', desc: '处理脑叶公司同事空床旁的遗留物。', tier: 'rare', group: '翼与巢', hidden: true, hint: '设施里也需要重新分配床位。' },
    wg_harbor: { name: '空泊位', desc: '核销大湖上多年未返的船号。', tier: 'rare', group: '翼与巢', hidden: true, hint: '返港以后仍有旧回执。' },
    wg_witness: { name: '见过的那一页', desc: '为N巢多年前的一次排查补齐证词。', tier: 'rare', group: '翼与巢', hidden: true, hint: '登记册不会很快销毁。' },
    wg_pawn: { name: '折痕', desc: '在J公司当铺认出换了编号的旧当物。', tier: 'rare', group: '翼与巢', hidden: true, hint: '赎期过后，东西未必离开柜台。' },
    wg_threshold: { name: '门外的工龄', desc: '核对鸿园封门后的外围送货路线。', tier: 'rare', group: '翼与巢', hidden: true, hint: '送货路线也会变更。' },
